  if (tokens.length === 0 || tokens[0] === 'null') return null
  const root = new TreeNode(Number(tokens[0]))
  const queue = [root]
  let head = 0, i = 1
  while (head < queue.length && i < tokens.length) {
    const node = queue[head++]
    if (i < tokens.length) {
